interface AnalyticsData {
  visits: number;
  bounceRate: number;
  activeUsers: number;
}

interface NotificationItem {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
}

interface SettingsData {
  theme: string;
  emailNotifications: boolean;
  pushNotifications: boolean;
}

// Follow pattern from page.tsx: Parallel data fetching with fallback
async function getDashboardData() {
  const API_BASE = 'http://localhost:3000'; // Helper for server-side absolute URLs

  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${API_BASE}/api/analytics`).then(r => r.json()),
      fetch(`${API_BASE}/api/notifications`).then(r => r.json()),
      fetch(`${API_BASE}/api/settings`).then(r => r.json())
    ]);

    return { 
      analytics: analytics as AnalyticsData, 
      notifications: notifications as NotificationItem[], 
      settings: settings as SettingsData 
    };
  } catch (error) {
    // Return mock data for build time or when APIs are unavailable
    return {
      analytics: { 
        visits: 1250, 
        bounceRate: 45.2, 
        activeUsers: 120 
      },
      notifications: [
        { id: 1, message: 'System update scheduled', type: 'info' },
        { id: 2, message: 'New user registered', type: 'info' }
      ] as NotificationItem[],
      settings: { 
        theme: 'light', 
        emailNotifications: true,
        pushNotifications: false
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="dashboard-container">
      <h2>Dashboard Content</h2>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginTop: '20px' }}>
        {/* Analytics Section */}
        <div style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
          <h3>Analytics</h3>
          <p><strong>Visits:</strong> {analytics.visits.toLocaleString()}</p>
          <p><strong>Active Users:</strong> {analytics.activeUsers}</p>
          <p><strong>Bounce Rate:</strong> {analytics.bounceRate}%</p>
        </div>

        {/* Notifications Section */}
        <div style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
          <h3>Notifications</h3>
          {notifications.length > 0 ? (
            <ul style={{ paddingLeft: '20px' }}>
              {notifications.map(n => (
                <li key={n.id} style={{ marginBottom: '5px' }}>
                  {n.message}
                </li>
              ))}
            </ul>
          ) : (
            <p>No new notifications</p>
          )}
        </div>

        {/* Settings Section */}
        <div style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
          <h3>Settings</h3>
          <p><strong>Theme:</strong> {settings.theme}</p>
          <p><strong>Email Alerts:</strong> {settings.emailNotifications ? 'On' : 'Off'}</p>
          <p><strong>Push Alerts:</strong> {settings.pushNotifications ? 'On' : 'Off'}</p>
        </div>
      </div>
    </div>
  );
}

